import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { supabase } from '../../lib/supabaseClient'

const inputStyle = { display: 'block', width: '100%', marginBottom: 10, padding: 10 }
const btnStyle = { padding: '10px 20px', marginTop: 12, marginRight: 8 }

type MenuItemDraft = { name: string; price: string }
type CategoryDraft = { name: string; items: MenuItemDraft[] }

export default function OnboardingWizard() {
  const navigate = useNavigate()
    const [step, setStep] = useState(1)
      const [error, setError] = useState('')
        const [loading, setLoading] = useState(false)
          const [restaurantId, setRestaurantId] = useState<string | null>(null)

            // Step 1
              const [restaurantName, setRestaurantName] = useState('')
                const [description, setDescription] = useState('')
                  const [phone, setPhone] = useState('')
                    const [email, setEmail] = useState('')
                      const [address, setAddress] = useState('')
                        const [city, setCity] = useState('')
                          const [state, setState] = useState('')

                            // Step 2
                              const [ownerName, setOwnerName] = useState('')
                                const [ownerEmail, setOwnerEmail] = useState('')
                                  const [ownerPhone, setOwnerPhone] = useState('')
                                    const [password, setPassword] = useState('')

                                      // Step 3
                                        const [primaryColor, setPrimaryColor] = useState('#1a1a1a')
                                          const [secondaryColor, setSecondaryColor] = useState('#ffffff')
                                            const [currency, setCurrency] = useState('NGN')
                                              const [slogan, setSlogan] = useState('')

                                                // Step 5: menu
                                                  const [categories, setCategories] = useState<CategoryDraft[]>([
                                                      { name: '', items: [{ name: '', price: '' }] },
                                                        ])

                                                          // Step 6: tables
                                                            const [tableCount, setTableCount] = useState('5')

                                                              function addCategory() {
                                                                  setCategories([...categories, { name: '', items: [{ name: '', price: '' }] }])
                                                                    }
                                                                      function updateCategoryName(i: number, value: string) {
                                                                          const next = [...categories]
                                                                              next[i].name = value
                                                                                  setCategories(next)
                                                                                    }
                                                                                      function addItem(catIndex: number) {
                                                                                          const next = [...categories]
                                                                                              next[catIndex].items.push({ name: '', price: '' })
                                                                                                  setCategories(next)
                                                                                                    }
                                                                                                      function updateItem(catIndex: number, itemIndex: number, field: 'name' | 'price', value: string) {
                                                                                                          const next = [...categories]
                                                                                                              next[catIndex].items[itemIndex][field] = value
                                                                                                                  setCategories(next)
                                                                                                                    }

                                                                                                                      // Step 1 -> 2: just validate, no DB write yet
                                                                                                                        function goStep2() {
                                                                                                                            setError('')
                                                                                                                                if (!restaurantName.trim()) {
                                                                                                                                      setError('Restaurant name is required')
                                                                                                                                            return
                                                                                                                                                }
                                                                                                                                                    setStep(2)
                                                                                                                                                      }

                                                                                                                                                        // Step 2 -> 3: create auth user + restaurant + profile now
                                                                                                                                                          async function goStep3() {
                                                                                                                                                              setError('')
                                                                                                                                                                  if (!ownerName.trim() || !ownerEmail.trim() || !password.trim()) {
                                                                                                                                                                        setError('Owner name, email and password are required')
                                                                                                                                                                              return
                                                                                                                                                                                  }
                                                                                                                                                                                      setLoading(true)

                                                                                                                                                                                          const { data: authData, error: authError } = await supabase.auth.signUp({
                                                                                                                                                                                                email: ownerEmail,
                                                                                                                                                                                                      password,
                                                                                                                                                                                                          })
                                                                                                                                                                                                              if (authError || !authData.user) {
                                                                                                                                                                                                                    setError(authError?.message || 'Signup failed')
                                                                                                                                                                                                                          setLoading(false)
                                                                                                                                                                                                                                return
                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                        const slug = restaurantName.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-')

                                                                                                                                                                                                                                            const { data: restaurant, error: restError } = await supabase
                                                                                                                                                                                                                                                  .from('restaurants')
                                                                                                                                                                                                                                                        .insert({ name: restaurantName, slug, description, phone, email, address, city, state })
                                                                                                                                                                                                                                                              .select()
                                                                                                                                                                                                                                                                    .single()

                                                                                                                                                                                                                                                                        if (restError || !restaurant) {
                                                                                                                                                                                                                                                                              setError(restError?.message || 'Could not create restaurant')
                                                                                                                                                                                                                                                                                    setLoading(false)
                                                                                                                                                                                                                                                                                          return
                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                  const { error: profileError } = await supabase.from('profiles').insert({
                                                                                                                                                                                                                                                                                                        id: authData.user.id,
                                                                                                                                                                                                                                                                                                              restaurant_id: restaurant.id,
                                                                                                                                                                                                                                                                                                                    role: 'restaurant_owner',
                                                                                                                                                                                                                                                                                                                          full_name: ownerName,
                                                                                                                                                                                                                                                                                                                                phone: ownerPhone,
                                                                                                                                                                                                                                                                                                                                    })

                                                                                                                                                                                                                                                                                                                                        if (profileError) {
                                                                                                                                                                                                                                                                                                                                              setError(profileError.message)
                                                                                                                                                                                                                                                                                                                                                    setLoading(false)
                                                                                                                                                                                                                                                                                                                                                          return
                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                  setRestaurantId(restaurant.id)
                                                                                                                                                                                                                                                                                                                                                                      setLoading(false)
                                                                                                                                                                                                                                                                                                                                                                          setStep(3)
                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                              // Step 3 -> 4: save branding
                                                                                                                                                                                                                                                                                                                                                                                async function goStep4() {
                                                                                                                                                                                                                                                                                                                                                                                    setError('')
                                                                                                                                                                                                                                                                                                                                                                                        setLoading(true)
                                                                                                                                                                                                                                                                                                                                                                                            const { error: updateError } = await supabase
                                                                                                                                                                                                                                                                                                                                                                                                  .from('restaurants')
                                                                                                                                                                                                                                                                                                                                                                                                        .update({ primary_color: primaryColor, secondary_color: secondaryColor, currency, slogan })
                                                                                                                                                                                                                                                                                                                                                                                                              .eq('id', restaurantId)

                                                                                                                                                                                                                                                                                                                                                                                                                  if (updateError) {
                                                                                                                                                                                                                                                                                                                                                                                                                        setError(updateError.message)
                                                                                                                                                                                                                                                                                                                                                                                                                              setLoading(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                    return
                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                            setLoading(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                setStep(4)
                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Step 4 -> 5: payment placeholder, just create a pending row
                                                                                                                                                                                                                                                                                                                                                                                                                                                      async function goStep5() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                          setError('')
                                                                                                                                                                                                                                                                                                                                                                                                                                                              setLoading(true)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const { error: payError } = await supabase.from('restaurant_payment_accounts').insert({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        restaurant_id: restaurantId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              provider: 'paystack',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    status: 'pending',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (payError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  setError(payError.message)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setLoading(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      setLoading(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          setStep(5)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Step 5 -> 6: save menu categories + items
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                async function goStep6() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setError('')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setLoading(true)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (const cat of categories) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!cat.name.trim()) continue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const { data: newCat, error: catError } = await supabase
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .from('menu_categories')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .insert({ restaurant_id: restaurantId, name: cat.name })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .select()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .single()

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (catError || !newCat) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      setError(catError?.message || 'Could not create category')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setLoading(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  for (const item of cat.items) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!item.name.trim() || !item.price.trim()) continue
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const { error: itemError } = await supabase.from('menu_items').insert({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            restaurant_id: restaurantId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      category_id: newCat.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                name: item.name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          price: parseFloat(item.price) || 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (itemError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    setError(itemError.message)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setLoading(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setLoading(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  setStep(6)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Step 6: finish - create tables
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        async function handleFinish() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            setError('')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                setLoading(true)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const count = parseInt(tableCount) || 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const tablesToInsert = Array.from({ length: count }, (_, i) => ({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              restaurant_id: restaurantId,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    table_number: String(i + 1),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }))

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (tablesToInsert.length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const { error: tableError } = await supabase.from('tables').insert(tablesToInsert)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (tableError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                setError(tableError.message)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        setLoading(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setLoading(false)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  alert(`${restaurantName} is fully set up! You can now log in.`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      navigate('/login')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div style={{ padding: 24, maxWidth: 420, margin: '0 auto' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h1>Create Your Restaurant</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p>Step {step} of 6</p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {step === 1 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h3>Restaurant Information</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input style={inputStyle} placeholder="Restaurant name" value={restaurantName} onChange={(e) => setRestaurantName(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <input style={inputStyle} placeholder="Business description" value={description} onChange={(e) => setDescription(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <input style={inputStyle} placeholder="Phone" value={phone} onChange={(e) => setPhone(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input style={inputStyle} placeholder="Business email" value={email} onChange={(e) => setEmail(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input style={inputStyle} placeholder="Address" value={address} onChange={(e) => setAddress(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <input style={inputStyle} placeholder="City" value={city} onChange={(e) => setCity(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <input style={inputStyle} placeholder="State" value={state} onChange={(e) => setState(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {step === 2 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <h3>Owner Account</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <input style={inputStyle} placeholder="Full name" value={ownerName} onChange={(e) => setOwnerName(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <input style={inputStyle} placeholder="Email" type="email" value={ownerEmail} onChange={(e) => setOwnerEmail(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input style={inputStyle} placeholder="Phone" value={ownerPhone} onChange={(e) => setOwnerPhone(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <input style={inputStyle} placeholder="Password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {step === 3 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <h3>Branding</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <label>Primary color</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <input style={inputStyle} type="color" value={primaryColor} onChange={(e) => setPrimaryColor(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <label>Secondary color</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input style={inputStyle} type="color" value={secondaryColor} onChange={(e) => setSecondaryColor(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <label>Currency</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <input style={inputStyle} value={currency} onChange={(e) => setCurrency(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <input style={inputStyle} placeholder="Slogan" value={slogan} onChange={(e) => setSlogan(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {step === 4 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h3>Payment Setup</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p>Paystack integration will be connected in a later step. For now, we'll mark your payment account as pending.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {step === 5 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h3>Menu Setup</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {categories.map((cat, ci) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div key={ci} style={{ marginBottom: 16, border: '1px solid #ccc', padding: 10 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input style={inputStyle} placeholder="Category name (e.g. Rice)" value={cat.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onChange={(e) => updateCategoryName(ci, e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {cat.items.map((item, ii) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div key={ii} style={{ display: 'flex', gap: 6, marginBottom: 6 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input placeholder="Item name" value={item.name}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onChange={(e) => updateItem(ci, ii, 'name', e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    style={{ flex: 2, padding: 8 }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <input placeholder="Price" value={item.price}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onChange={(e) => updateItem(ci, ii, 'price', e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style={{ flex: 1, padding: 8 }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button type="button" onClick={() => addItem(ci)}>+ Add Item</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button type="button" onClick={addCategory}>+ Add Category</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {step === 6 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <h3>Table Setup</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <label>How many tables?</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input style={inputStyle} type="number" value={tableCount} onChange={(e) => setTableCount(e.target.value)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p>We'll create Table 1 through Table {tableCount || 0}.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {error && <p style={{ color: 'red' }}>{error}</p>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {step === 1 && <button style={btnStyle} onClick={goStep2} disabled={loading}>Next</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {step === 2 && <button style={btnStyle} onClick={goStep3} disabled={loading}>{loading ? 'Creating...' : 'Next'}</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {step === 3 && <button style={btnStyle} onClick={goStep4} disabled={loading}>{loading ? 'Saving...' : 'Next'}</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {step === 4 && <button style={btnStyle} onClick={goStep5} disabled={loading}>{loading ? 'Saving...' : 'Next'}</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {step === 5 && <button style={btnStyle} onClick={goStep6} disabled={loading}>{loading ? 'Saving...' : 'Next'}</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {step === 6 && <button style={btnStyle} onClick={handleFinish} disabled={loading}>{loading ? 'Finishing...' : 'Finish Setup'}</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    